	b, baseHeaderOK := parseMergeMethodHeader(baseLines)
	if !sourceHeaderOK || !baseHeaderOK {
		return "", fmt.Errorf("unsupported_signature")
	}
	function := func(s string) bool { return strings.EqualFold(s, "функция") || strings.EqualFold(s, "function") }
