	baseComments := mergeMethodComments(baseLines[:b.endLine])
	if strings.Join(sourceComments, "\n") != strings.Join(baseComments, "\n") {
		result = append(result, sourceComments...)
	}
	result = append(result, lines[a.endLine:]...)
	return strings.Join(result, "\n"), nil
