var mergeParameterNameRE = regexp.MustCompile(`^[\p{L}_][\p{L}\p{N}_]*$`)

// Interceptors receive the original method's arguments; defaults belong to its
// retained header. Names, order and by-value modifiers must still match because
// the replacement body is copied without rewriting parameter references.
func mergeParameterBindings(signature string) (string, bool) {
	tokens := mergeTokens(signature)
	if len(tokens) < 2 || tokens[0] != "(" || tokens[len(tokens)-1] != ")" {
		return "", false
	}
	tokens = tokens[1 : len(tokens)-1]
	bindings := [][]string{}
	if len(tokens) == 0 {
		return "[]", true
	}
	start, depth := 0, 0
	for i := 0; i <= len(tokens); i++ {
		if i == len(tokens) || (tokens[i] == "," && depth == 0) {
			if depth != 0 || start == i {
				return "", false
			}
			binding := append([]string(nil), tokens[start:i]...)
			for j, token := range binding {
				if token == "=" {
					if j == len(binding)-1 {
						return "", false
					}
					binding = binding[:j]
					break
				}
			}
			if len(binding) == 2 && (binding[0] == "знач" || binding[0] == "val") {
				binding[0] = "val"
			} else if len(binding) != 1 {
				return "", false
			}
			if !mergeParameterNameRE.MatchString(binding[len(binding)-1]) {
				return "", false
			}
			bindings = append(bindings, binding)
			start = i + 1
			continue
		}
		switch tokens[i] {
		case "(":
			depth++
		case ")":
			depth--
			if depth < 0 {
				return "", false
			}
		}
	}
	encoded, _ := json.Marshal(bindings)
	return string(encoded), true
}

func splitChangeControl(source string) (string, string, error) {
	var original, changed []string
	state := ""
	inString := false
	for _, line := range strings.Split(source, "\n") {
		startsInString := inString
		code, comment := mergeSplitComment(line, &inString)
		directive := strings.ToLower(strings.TrimSpace(code))
		if startsInString {

			directive = ""
		}
		switch directive {
		case "#вставить", "#вставка", "#insert":
			if state != "" {
				return "", "", fmt.Errorf("nested_change_marker")
			}
			state = "insert"
		case "#удалить", "#удаление", "#delete":
			if state != "" {
				return "", "", fmt.Errorf("nested_change_marker")
			}
			state = "delete"
		case "#конецвставить", "#конецвставки", "#endinsert":
			if state != "insert" {
				return "", "", fmt.Errorf("unmatched_insert_end")
			}
			state = ""
		case "#конецудалить", "#конецудаления", "#enddelete":
			if state != "delete" {
				return "", "", fmt.Errorf("unmatched_delete_end")
			}
			state = ""
		default:
			if state != "insert" {
				original = append(original, line)
			}
			if state != "delete" {
				changed = append(changed, line)
			} else if comment != "" {

				changed = append(changed, comment)
			}
			continue
		}

		if comment != "" {
			original = append(original, comment)
			changed = append(changed, comment)
		}
	}
	if state != "" {
		return "", "", fmt.Errorf("unclosed_change_marker")
	}
	return strings.Join(original, "\n"), strings.Join(changed, "\n"), nil
}

